CREATE TABLE `partner_organizations` (`id` text PRIMARY KEY NOT NULL, `name` text NOT NULL, `contact_email` text NOT NULL, `website` text, `country` text, `description` text, `support_contact` text, `verification_status` text NOT NULL DEFAULT 'draft', `marketplace_status` text NOT NULL DEFAULT 'draft', `created_at` integer NOT NULL, `updated_at` integer NOT NULL);
CREATE TABLE `partner_products` (`id` text PRIMARY KEY NOT NULL, `partner_id` text NOT NULL, `name` text NOT NULL, `type` text NOT NULL, `description` text NOT NULL, `status` text NOT NULL DEFAULT 'draft', `verified` integer NOT NULL DEFAULT 0, `created_at` integer NOT NULL, `updated_at` integer NOT NULL);
CREATE TABLE `partner_product_versions` (`id` text PRIMARY KEY NOT NULL, `product_id` text NOT NULL, `version` text NOT NULL, `release_notes` text, `manifest` text NOT NULL, `status` text NOT NULL DEFAULT 'draft', `created_at` integer NOT NULL);
CREATE TABLE `developer_api_keys` (`id` text PRIMARY KEY NOT NULL, `partner_id` text NOT NULL, `key_hash` text NOT NULL UNIQUE, `scopes` text NOT NULL, `revoked_at` integer, `last_used_at` integer, `created_at` integer NOT NULL);